-- LOCAL DEVELOPMENT ONLY. Explicit demo import, NOT a Flyway migration.
-- Appends 4 demo authors and the 24 existing Markdown fixtures.
-- Demo-only password: TechVerseDemo@2026 (stored as a BCrypt hash).
-- Covers: external Unsplash URLs, not Cloudinary-managed uploads.
-- Re-run safely; existing records are never updated or deleted.
BEGIN;
SET LOCAL search_path TO techverse, public;
SET LOCAL TIME ZONE 'Asia/Ho_Chi_Minh';

DO $guard$
BEGIN
    IF current_database() <> 'techverse' THEN
        RAISE EXCEPTION 'Demo seed is restricted to database techverse';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id = u.id
        JOIN roles r ON r.id = ur.role_id WHERE u.is_active AND r.name = 'ADMIN'
    ) THEN
        RAISE EXCEPTION 'An active ADMIN is required';
    END IF;
    IF (SELECT count(*) FROM roles WHERE name IN ('LEARNER', 'AUTHOR')) <> 2 THEN
        RAISE EXCEPTION 'Required roles are missing';
    END IF;
END
$guard$;

