INSERT INTO demo_payload VALUES ($demo_data${"authors":[{"ordinal":1,"name":"Nguyễn Minh An","email":"author01@demo.techverse.test","expertise":"Java, Spring Boot, Security","bio":"Tác giả demo chia sẻ kiến thức backend Java và thiết kế hệ thống."},{"ordinal":2,"name":"Trần Hoàng Linh","email":"author02@demo.techverse.test","expertise":"React, TypeScript, Web Performance","bio":"Tác giả demo chuyên về frontend và trải nghiệm phát triển ứng dụng web."},{"ordinal":3,"name":"Lê Quang Huy","email":"author03@demo.techverse.test","expertise":"PostgreSQL, Redis, System Design","bio":"Tác giả demo chia sẻ kinh nghiệm dữ liệu, caching và xử lý đồng thời."},{"ordinal":4,"name":"Phạm Thu Hà","email":"author04@demo.techverse.test","expertise":"Docker, DevOps, Software Testing","bio":"Tác giả demo viết về triển khai, kiểm thử và làm việc nhóm."}],"articles":[{"file":"articles/01-java-oop-composition.md","title":"Java OOP: ưu tiên composition khi xây dựng dịch vụ thông báo","summary":"Phân biệt kế thừa và composition qua ví dụ gửi thông báo, giúp thay đổi kênh gửi mà không sửa logic nghiệp vụ.","topicName":"Java Core","tagNames":["Java","OOP","Collections","Streams"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# Java OOP: ưu tiên composition khi xây dựng dịch vụ thông báo\n\nPhân biệt kế thừa và composition qua ví dụ gửi thông báo, giúp thay đổi kênh gửi mà không sửa logic nghiệp vụ.\n\n## Bối cảnh\n\nMột dịch vụ đăng ký có thể gửi thông báo qua email hôm nay và thêm kênh khác sau này. Nếu logic đăng ký phụ thuộc trực tiếp vào một lớp gửi cụ thể, mỗi thay đổi hạ tầng dễ kéo theo thay đổi nghiệp vụ.\n\n## Ý tưởng chính\n\nComposition nghĩa là một đối tượng sử dụng đối tượng khác để hoàn thành công việc. Interface mô tả điều cần làm, còn lớp triển khai quyết định làm thế nào. Không cần tạo một cây kế thừa chỉ để tái sử dụng vài dòng code.\n\n## Ví dụ minh họa\n\n```java\ninterface NotificationSender {\n    void send(String recipient, String message);\n}\n\nfinal class ConsoleSender implements NotificationSender {\n    @Override\n    public void send(String recipient, String message) {\n        System.out.println(recipient + \": \" + message);\n    }\n}\n\nfinal class RegistrationNotice {\n    private final NotificationSender sender;\n\n    RegistrationNotice(NotificationSender sender) {\n        this.sender = sender;\n    }\n\n    void welcome(String email) {\n        sender.send(email, \"Chào mừng đến với TechVerse!\");\n    }\n}\n```\n\n## Phân tích từng bước\n\n1. RegistrationNotice phụ thuộc vào hợp đồng NotificationSender, không biết nhà cung cấp email.\n2. ConsoleSender là ví dụ minh họa; thay bằng adapter gửi email không làm đổi hàm welcome.\n3. Constructor thể hiện rõ phụ thuộc cần có để đối tượng hoạt động.\n\n## Lỗi thường gặp\n\n- Không tạo interface cho mọi lớp theo thói quen; ưu tiên các ranh giới thật sự cần thay thế.\n- Không ghi email, mật khẩu hoặc token thật vào log khi triển khai thực tế.\n- Composition không loại bỏ hoàn toàn kế thừa; chọn theo quan hệ nghiệp vụ.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nTạo một FakeSender lưu thông báo vào danh sách, sau đó kiểm tra welcome chỉ gửi đúng một thông báo.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Phân biệt kế thừa và composition qua ví dụ gửi thông báo, giúp thay đổi kênh gửi mà không sửa logic nghiệp vụ.\n","ordinal":1,"authorOrdinal":1},{"file":"articles/02-spring-service-transaction.md","title":"Spring Boot: đặt ranh giới giao dịch ở service thay vì controller","summary":"Tổ chức controller, service và repository qua tình huống đổi tiêu đề bài viết trong một giao dịch.","topicName":"Spring Boot","tagNames":["Spring Boot","Dependency Injection","Bean Validation","Transactions"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# Spring Boot: đặt ranh giới giao dịch ở service thay vì controller\n\nTổ chức controller, service và repository qua tình huống đổi tiêu đề bài viết trong một giao dịch.\n\n## Bối cảnh\n\nMột API ngắn không đồng nghĩa toàn bộ xử lý phải nằm trong controller. Controller tập trung vào giao tiếp HTTP; service thể hiện quy tắc và ranh giới giao dịch; repository phụ trách truy cập dữ liệu.\n\n## Ý tưởng chính\n\nTrong ví dụ, bài viết được tải, kiểm tra chủ sở hữu rồi mới sửa. Tất cả nằm trong một transaction. Nếu quy tắc không thỏa mãn, thao tác dừng trước khi commit. Đây là đoạn rút gọn, không thay thế cơ chế khóa hoặc kiểm tra trạng thái khi cập nhật đồng thời.\n\n## Ví dụ minh họa\n\n```java\n@Service\n@RequiredArgsConstructor\npublic class RenameArticleService {\n    private final ArticleRepository articles;\n\n    @Transactional\n    public void rename(UUID actorId, UUID articleId, String title) {\n        if (title == null || title.isBlank()) {\n            throw new IllegalArgumentException(\"Title is required\");\n        }\n\n        Article article = articles.findById(articleId)\n            .orElseThrow(() -> new IllegalArgumentException(\"Not found\"));\n\n        if (!article.getAuthor().getId().equals(actorId)) {\n            throw new SecurityException(\"Not the owner\");\n        }\n\n        article.setTitle(title.strip());\n    }\n}\n```\n\n## Phân tích từng bước\n\n1. Constructor injection giúp khai báo phụ thuộc một cách tường minh.\n2. Entity được quản lý trong persistence context nên thay đổi có thể được ghi bằng dirty checking.\n3. Trong dự án thật, thay exception minh họa bằng CustomException và ErrorCode thống nhất.\n\n## Lỗi thường gặp\n\n- @Transactional không tự giải quyết hai request cùng sửa một bản ghi.\n- Gọi hàm transactional từ chính đối tượng đó thường không đi qua proxy như lời gọi từ bean khác.\n- Không giữ transaction mở trong khi chờ một API bên ngoài phản hồi lâu.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nBổ sung kiểm tra chỉ DRAFT hoặc CHANGES_REQUESTED được đổi tiêu đề, rồi liệt kê test cho tác giả khác và trạng thái PENDING.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Tổ chức controller, service và repository qua tình huống đổi tiêu đề bài viết trong một giao dịch.\n","ordinal":2,"authorOrdinal":1},{"file":"articles/03-postgresql-index-pagination.md","title":"PostgreSQL: thiết kế index cho danh sách bài viết theo topic","summary":"Đọc điều kiện lọc, thứ tự sắp xếp và EXPLAIN để chọn index phù hợp với truy vấn bài viết.","topicName":"Database & SQL","tagNames":["PostgreSQL","SQL","Indexing","Flyway"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# PostgreSQL: thiết kế index cho danh sách bài viết theo topic\n\nĐọc điều kiện lọc, thứ tự sắp xếp và EXPLAIN để chọn index phù hợp với truy vấn bài viết.\n\n## Bối cảnh\n\nDanh sách bài viết thường lọc theo topic và trạng thái, rồi sắp xếp theo ngày xuất bản. Index nên xuất phát từ truy vấn thật thay vì tạo cho mọi cột.\n\n## Ý tưởng chính\n\nIndex tổng hợp có thể phục vụ một tổ hợp điều kiện cụ thể. Việc PostgreSQL có dùng nó hay không còn phụ thuộc dữ liệu, thống kê và chi phí ước lượng. Hãy kiểm tra kế hoạch trước khi kết luận index hiệu quả.\n\n## Ví dụ minh họa\n\n```sql\n-- Thay UUID mẫu bằng topic có dữ liệu trong môi trường test.\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT id, title, summary, published_at\nFROM techverse.articles\nWHERE topic_id = '00000000-0000-0000-0000-000000000001'\n  AND status = 'PUBLISHED'\nORDER BY published_at DESC, id DESC\nLIMIT 20;\n\n-- Chỉ nghiên cứu trên DB test; không tạo index trùng trong dự án.\n-- Schema TechVerse đã có index topic/status/published_at.\n```\n\n## Phân tích từng bước\n\n1. WHERE cho biết các cột lọc chính của truy vấn.\n2. ORDER BY có id làm tiêu chí phụ để kết quả không đổi thứ tự khi trùng thời gian.\n3. EXPLAIN ANALYZE thực thi truy vấn; chỉ dùng với thao tác và môi trường đã hiểu rõ.\n\n## Lỗi thường gặp\n\n- Bảng nhỏ có thể dùng sequential scan hợp lý hơn index scan.\n- Index làm tăng dung lượng và chi phí ghi, không miễn phí.\n- Không chạy lệnh tạo index minh họa vào production khi chưa xem các index hiện có.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nSo sánh kế hoạch với topic có ít bài và topic có nhiều bài; ghi lại số hàng thực tế và lượng buffer đọc.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Đọc điều kiện lọc, thứ tự sắp xếp và EXPLAIN để chọn index phù hợp với truy vấn bài viết.\n","ordinal":3,"authorOrdinal":3},{"file":"articles/04-redis-cache-aside.md","title":"Redis: hiểu cache-aside và TTL qua thông tin topic","summary":"Mô tả luồng đọc cache, đọc database khi miss và xóa cache sau khi cập nhật dữ liệu.","topicName":"Redis & Caching","tagNames":["Redis","Caching","TTL","Cache Aside"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# Redis: hiểu cache-aside và TTL qua thông tin topic\n\nMô tả luồng đọc cache, đọc database khi miss và xóa cache sau khi cập nhật dữ liệu.\n\n## Bối cảnh\n\nCache giúp giảm những lần đọc lặp lại, nhưng nó tạo thêm một bản sao của dữ liệu. Cần quyết định cache có thể cũ bao lâu và phải làm gì khi nguồn dữ liệu thay đổi.\n\n## Ý tưởng chính\n\nVới cache-aside, ứng dụng kiểm tra cache trước. Khi cache miss, ứng dụng đọc database và ghi kết quả vào cache với TTL. Pseudocode dưới đây minh họa luồng, không phải chức năng cache đã được cài trong TechVerse.\n\n## Ví dụ minh họa\n\n```text\nreadTopic(topicId):\n    key = \"topic:\" + topicId\n    cached = redis.get(key)\n    if cached exists:\n        return deserialize(cached)\n\n    topic = database.findTopic(topicId)\n    if topic does not exist:\n        return NOT_FOUND\n\n    redis.set(key, serialize(topic), ttl = 60 seconds)\n    return topic\n\nupdateTopic(topicId, changes):\n    database.updateAndCommit(topicId, changes)\n    redis.delete(\"topic:\" + topicId)\n```\n\n## Phân tích từng bước\n\n1. TTL giới hạn thời gian tồn tại của bản sao, không bảo đảm dữ liệu luôn mới.\n2. Chỉ xóa cache sau khi giao dịch database commit thành công.\n3. Đối với dữ liệu phân quyền, không tùy tiện dùng cùng mức chấp nhận stale như nội dung công khai.\n\n## Lỗi thường gặp\n\n- Hai request miss cùng lúc vẫn có thể đọc DB; cache-aside cơ bản không chống stampede.\n- Một lần đọc cũ đang chạy có thể ghi lại cache sau lần xóa; cần chiến lược bổ sung nếu yêu cầu nhất quán cao.\n- Không dùng Redis cache làm nguồn dữ liệu duy nhất cho nghiệp vụ cần lưu bền.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nVẽ timeline hai request: một request đọc topic trong lúc admin đổi trạng thái; chỉ ra nơi có thể xuất hiện cache cũ.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Mô tả luồng đọc cache, đọc database khi miss và xóa cache sau khi cập nhật dữ liệu.\n","ordinal":4,"authorOrdinal":3},{"file":"articles/05-auth-session-token.md","title":"JWT và session: vì sao logout cần nhiều hơn xóa cookie","summary":"Phân biệt thời hạn token, trạng thái phiên ở Redis và tác dụng thật của thao tác logout.","topicName":"Authentication & Security","tagNames":["JWT","OAuth2","Spring Security","Session Management"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# JWT và session: vì sao logout cần nhiều hơn xóa cookie\n\nPhân biệt thời hạn token, trạng thái phiên ở Redis và tác dụng thật của thao tác logout.\n\n## Bối cảnh\n\nXóa token khỏi trình duyệt không đồng nghĩa vô hiệu hóa mọi bản sao của token đó. Người dùng có thể đã mở tab khác, hoặc một client vẫn giữ access token cũ.\n\n## Ý tưởng chính\n\nJWT có thể được xác minh chữ ký mà không cần hỏi database. Nếu hệ thống muốn logout có hiệu lực trước exp, cần kiểm tra thêm trạng thái thu hồi hoặc session. Ví dụ dưới mô tả sessionId ổn định cho một lần đăng nhập, không yêu cầu mọi dự án phải dùng đúng một mô hình.\n\n## Ví dụ minh họa\n\n```text\nlogin:\n    create session sid owned by userId\n    issue access token with sub=userId, sid=sid, exp=...\n    issue refresh credential associated with sid\n\nauthenticated request:\n    verify signature, issuer, audience and expiry\n    require token type = ACCESS\n    require session sid exists and belongs to sub\n    enforce endpoint permissions\n\nlogout current device:\n    authenticate caller\n    invalidate caller session sid\n    clear refresh cookie with matching cookie scope\n```\n\n## Phân tích từng bước\n\n1. sub nhận diện người dùng; sid nhận diện một phiên đăng nhập cụ thể.\n2. Hai trình duyệt có thể cùng userId nhưng khác sid.\n3. Backend kiểm tra quyền; ẩn nút ở giao diện không phải biện pháp phân quyền.\n\n## Lỗi thường gặp\n\n- Không đưa mật khẩu, API key hoặc dữ liệu nhạy cảm vào JWT payload.\n- Không chấp nhận refresh token làm access token.\n- Refresh đồng thời với logout cần cập nhật Redis nguyên tử để tránh hồi sinh phiên.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nViết checklist test login ở hai trình duyệt, logout một phiên, rồi thử lại access token của cả hai phiên.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Phân biệt thời hạn token, trạng thái phiên ở Redis và tác dụng thật của thao tác logout.\n","ordinal":5,"authorOrdinal":1},{"file":"articles/06-javascript-async-await.md","title":"JavaScript: xử lý lỗi HTTP đúng khi dùng async/await","summary":"Tách lỗi kết nối và lỗi HTTP, kiểm tra response.ok và không nuốt thông báo lỗi từ server.","topicName":"JavaScript","tagNames":["JavaScript","Async Await","Promises","Event Loop"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# JavaScript: xử lý lỗi HTTP đúng khi dùng async/await\n\nTách lỗi kết nối và lỗi HTTP, kiểm tra response.ok và không nuốt thông báo lỗi từ server.\n\n## Bối cảnh\n\nfetch trả về một Promise, nhưng phản hồi HTTP 404 hoặc 500 không tự làm Promise bị reject. Nếu chỉ viết try/catch mà không kiểm tra status, giao diện có thể báo thành công sai.\n\n## Ý tưởng chính\n\nHàm dưới đọc dữ liệu JSON và dừng khi response không thành công. Dự án có API client dùng chung thì nên xử lý ở client đó, thay vì sao chép nhiều hàm fetch rời rạc.\n\n## Ví dụ minh họa\n\n```javascript\nasync function loadArticles(signal) {\n  const response = await fetch(\"/api/v1/articles\", {\n    signal,\n    credentials: \"include\"\n  });\n\n  const payload = await response.json().catch(() => null);\n\n  if (!response.ok) {\n    throw new Error(payload?.message ?? \"Không thể tải bài viết\");\n  }\n\n  return payload?.data;\n}\n\nasync function showArticles(signal) {\n  try {\n    return await loadArticles(signal);\n  } catch (error) {\n    if (error instanceof Error && error.name === \"AbortError\") return;\n    throw error;\n  }\n}\n```\n\n## Phân tích từng bước\n\n1. response.ok kiểm tra status thuộc nhóm thành công.\n2. Không giả định mọi phản hồi, kể cả từ proxy, đều có JSON hợp lệ.\n3. AbortError là tình huống hủy chủ động; không nhất thiết hiển thị như lỗi hệ thống.\n\n## Lỗi thường gặp\n\n- Ví dụ fetch không thay thế Bearer token và luồng refresh của API client thật.\n- Không log toàn bộ header Authorization khi debug.\n- Đừng biến mọi lỗi thành mảng rỗng vì sẽ che mất lỗi quyền truy cập.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nGiả lập phản hồi 200, 401, 403, 500 và HTML không phải JSON; mô tả giao diện nên hiển thị gì.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Tách lỗi kết nối và lỗi HTTP, kiểm tra response.ok và không nuốt thông báo lỗi từ server.\n","ordinal":6,"authorOrdinal":2},{"file":"articles/07-typescript-discriminated-union.md","title":"TypeScript: mô hình hóa trạng thái tải dữ liệu bằng union","summary":"Dùng discriminated union để tránh tổ hợp trạng thái loading, data và error mâu thuẫn nhau.","topicName":"TypeScript","tagNames":["TypeScript","Generics","Type Guards","Utility Types"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# TypeScript: mô hình hóa trạng thái tải dữ liệu bằng union\n\nDùng discriminated union để tránh tổ hợp trạng thái loading, data và error mâu thuẫn nhau.\n\n## Bối cảnh\n\nNếu dùng ba biến độc lập cho loading, data và error, giao diện có thể vô tình giữ lỗi cũ khi dữ liệu mới đã về. Một mô hình trạng thái rõ ràng giúp giảm những tổ hợp không hợp lệ.\n\n## Ý tưởng chính\n\nDiscriminated union dùng một trường nhận diện, ở đây là status. Khi kiểm tra trường này, TypeScript thu hẹp kiểu tương ứng. Điều đó không thay thế kiểm tra dữ liệu nhận từ mạng tại runtime.\n\n## Ví dụ minh họa\n\n```typescript\ntype Article = { id: string; title: string };\n\ntype RemoteData<T> =\n  | { status: \"idle\" }\n  | { status: \"loading\" }\n  | { status: \"success\"; data: T }\n  | { status: \"error\"; message: string };\n\nfunction describe(state: RemoteData<Article[]>): string {\n  switch (state.status) {\n    case \"idle\": return \"Chưa tải\";\n    case \"loading\": return \"Đang tải...\";\n    case \"error\": return state.message;\n    case \"success\": return `Có ${state.data.length} bài viết`;\n  }\n}\n```\n\n## Phân tích từng bước\n\n1. Mỗi nhánh chỉ có các trường hợp lệ cho trạng thái đó.\n2. Trường data không tồn tại ở nhánh loading nên không bị đọc nhầm.\n3. Generic T cho phép tái sử dụng mô hình với danh sách topic hoặc thông tin cá nhân.\n\n## Lỗi thường gặp\n\n- Ép kiểu bằng as không xác thực JSON trả về.\n- Không tạo union quá lớn chứa toàn bộ trạng thái của cả ứng dụng.\n- Không giữ token thật trong fixture để tiện thử.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThêm trạng thái refreshing có dữ liệu cũ, sau đó sửa hàm describe để thể hiện rõ đang làm mới.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Dùng discriminated union để tránh tổ hợp trạng thái loading, data và error mâu thuẫn nhau.\n","ordinal":7,"authorOrdinal":2},{"file":"articles/08-react-controlled-form.md","title":"React: form có kiểm soát và chống bấm lưu liên tục","summary":"Kết hợp state hiển thị với ref khóa thao tác để tránh gửi nhiều request do nhấp nhanh.","topicName":"React","tagNames":["React","Hooks","Forms","State Management"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# React: form có kiểm soát và chống bấm lưu liên tục\n\nKết hợp state hiển thị với ref khóa thao tác để tránh gửi nhiều request do nhấp nhanh.\n\n## Bối cảnh\n\nNút disabled giúp người dùng hiểu form đang xử lý, nhưng state chỉ thay đổi ở lần render tiếp theo. Với thao tác quan trọng, một ref có thể chặn lời gọi lặp ngay trong cùng nhịp xử lý.\n\n## Ý tưởng chính\n\nVí dụ dưới minh họa form tối giản. Khóa trên frontend chỉ hỗ trợ trải nghiệm; backend vẫn cần unique constraint, transaction hoặc idempotency tùy nghiệp vụ.\n\n## Ví dụ minh họa\n\n```jsx\nimport { useRef, useState } from \"react\";\n\nexport function TitleForm({ onSave }) {\n  const [title, setTitle] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const inFlight = useRef(false);\n\n  async function submit(event) {\n    event.preventDefault();\n    if (inFlight.current || !title.trim()) return;\n    inFlight.current = true;\n    setBusy(true);\n    try {\n      await onSave(title.trim());\n    } finally {\n      inFlight.current = false;\n      setBusy(false);\n    }\n  }\n\n  return (\n    <form onSubmit={submit}>\n      <label>Tiêu đề<input value={title}\n        onChange={e => setTitle(e.target.value)} /></label>\n      <button disabled={busy}>Lưu</button>\n    </form>\n  );\n}\n```\n\n## Phân tích từng bước\n\n1. State làm giao diện cập nhật; ref lưu khóa đồng bộ giữa các lời gọi.\n2. finally giải phóng khóa cả khi thao tác thất bại.\n3. Component cha cần xử lý thông báo lỗi của onSave; đoạn này tập trung riêng vào cơ chế khóa.\n\n## Lỗi thường gặp\n\n- Chặn double-click không ngăn client khác gửi hai request.\n- Không đặt mọi thứ vào useEffect khi hành động thực sự xuất phát từ nút bấm.\n- Không chỉnh sửa trực tiếp state.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThêm thông báo lỗi, rồi test bằng một onSave chậm và hai lần submit liên tiếp.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Kết hợp state hiển thị với ref khóa thao tác để tránh gửi nhiều request do nhấp nhanh.\n","ordinal":8,"authorOrdinal":2},{"file":"articles/09-nextjs-route-layout.md","title":"Next.js: tổ chức route và layout cho khu vực tác giả","summary":"Minh họa cách phân nhóm trang bài viết và tái sử dụng layout trong ứng dụng dùng App Router.","topicName":"Next.js","tagNames":["Next.js","SSR","Routing","Server Components"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Next.js: tổ chức route và layout cho khu vực tác giả\n\nMinh họa cách phân nhóm trang bài viết và tái sử dụng layout trong ứng dụng dùng App Router.\n\n## Bối cảnh\n\nKhi số trang tăng lên, việc lặp lại sidebar ở từng trang dễ gây lệch giao diện. Layout dùng chung giúp tổ chức phần khung và để page tập trung vào nội dung.\n\n## Ý tưởng chính\n\nĐây là nội dung học tập dành cho một ứng dụng Next.js riêng. Frontend TechVerse hiện dùng React/Vite, không cần chuyển cấu trúc đang có sang Next.js để import bài này.\n\n## Ví dụ minh họa\n\n```text\napp/\n  layout.tsx\n  author/\n    layout.tsx\n    articles/\n      page.tsx\n      new/\n        page.tsx\n      [id]/\n        page.tsx\n\nauthor/layout.tsx:\n    render author navigation\n    render children\n\nauthor/articles/page.tsx:\n    render article list\n\nauthor/articles/[id]/page.tsx:\n    render selected article\n```\n\n## Phân tích từng bước\n\n1. Layout thể hiện cấu trúc giao diện dùng chung cho nhóm trang.\n2. Route động thể hiện tài nguyên có id, không đồng nghĩa người dùng được phép xem mọi id.\n3. Các kiểm tra bảo mật thực tế phải có ở backend và ranh giới dữ liệu thích hợp.\n\n## Lỗi thường gặp\n\n- Không lưu secret trong module hoặc biến môi trường được đưa ra client.\n- Layout không thay thế kiểm tra quyền sở hữu bài viết.\n- Đừng suy luận framework của một dự án chỉ từ tên thư mục app.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThiết kế thêm nhóm route moderator với layout riêng, nhưng cùng dùng một component hiển thị nội dung Markdown.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Minh họa cách phân nhóm trang bài viết và tái sử dụng layout trong ứng dụng dùng App Router.\n","ordinal":9,"authorOrdinal":2},{"file":"articles/10-css-responsive-accessibility.md","title":"HTML và CSS: xây dựng thẻ bài viết responsive dễ sử dụng","summary":"Thiết kế bố cục thẻ bài viết không tràn màn hình và có trạng thái focus rõ cho bàn phím.","topicName":"HTML & CSS","tagNames":["HTML","CSS","Flexbox","Accessibility"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# HTML và CSS: xây dựng thẻ bài viết responsive dễ sử dụng\n\nThiết kế bố cục thẻ bài viết không tràn màn hình và có trạng thái focus rõ cho bàn phím.\n\n## Bối cảnh\n\nMột thẻ bài viết cần đọc được ở màn hình nhỏ và thao tác được bằng bàn phím. Chỉ căn đẹp trên desktop chưa đủ để đánh giá giao diện.\n\n## Ý tưởng chính\n\nDùng phần tử có ngữ nghĩa trước, sau đó bổ sung CSS. Tiêu đề dài nên được xuống dòng thay vì làm khối cha tràn ngang. Focus-visible giúp người dùng biết vị trí khi điều hướng không dùng chuột.\n\n## Ví dụ minh họa\n\n```css\n.article-card {\n  display: flex;\n  flex-direction: column;\n  gap: 0.75rem;\n  min-width: 0;\n  border: 1px solid #cbd5e1;\n  border-radius: 1rem;\n  padding: 1rem;\n}\n\n.article-card h2 {\n  overflow-wrap: anywhere;\n  margin: 0;\n}\n\n.article-card a:focus-visible {\n  outline: 3px solid #2563eb;\n  outline-offset: 4px;\n}\n\n.article-card-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));\n  gap: 1rem;\n}\n```\n\n## Phân tích từng bước\n\n1. Dùng article cho một nội dung độc lập và heading đúng cấp.\n2. Dùng thẻ a cho điều hướng, button cho hành động.\n3. Kiểm tra cả nền sáng và nền tối thay vì giả định một màu luôn đủ tương phản.\n\n## Lỗi thường gặp\n\n- Không bỏ outline mà không cung cấp chỉ báo focus khác.\n- Ảnh có ý nghĩa cần alt phù hợp; ảnh trang trí dùng alt rỗng.\n- Không dùng fixed width lớn cho toàn bộ card.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThử tiêu đề 200 ký tự, zoom 200% và màn hình rộng 320px; ghi lại vị trí bị tràn nếu có.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Thiết kế bố cục thẻ bài viết không tràn màn hình và có trạng thái focus rõ cho bàn phím.\n","ordinal":10,"authorOrdinal":2},{"file":"articles/11-node-error-handling.md","title":"Node.js: phản hồi lỗi nhất quán trong HTTP server","summary":"Phân biệt lỗi nghiệp vụ với lỗi bất ngờ và tránh để lộ stack trace trong phản hồi HTTP.","topicName":"Node.js","tagNames":["Node.js","Express","Middleware","Error Handling"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# Node.js: phản hồi lỗi nhất quán trong HTTP server\n\nPhân biệt lỗi nghiệp vụ với lỗi bất ngờ và tránh để lộ stack trace trong phản hồi HTTP.\n\n## Bối cảnh\n\nLỗi không chỉ là một dòng log. Client cần status rõ ràng và thông báo có thể hiển thị, còn thông tin chẩn đoán chi tiết nên nằm ở phía server.\n\n## Ý tưởng chính\n\nVí dụ dùng HTTP server tích hợp của Node.js để minh họa hai nhánh 404 và 500. Với ứng dụng framework, đặt cơ chế chuyển lỗi tại middleware hoặc bộ xử lý lỗi tập trung.\n\n## Ví dụ minh họa\n\n```javascript\nimport { createServer } from \"node:http\";\n\nfunction json(response, status, body) {\n  response.writeHead(status, { \"Content-Type\": \"application/json; charset=utf-8\" });\n  response.end(JSON.stringify(body));\n}\n\ncreateServer(async (request, response) => {\n  try {\n    if (request.method === \"GET\" && request.url === \"/health\") {\n      json(response, 200, { status: \"ok\" });\n      return;\n    }\n\n    json(response, 404, { code: \"NOT_FOUND\", message: \"Không tìm thấy tài nguyên\" });\n  } catch {\n    if (!response.headersSent) {\n      json(response, 500, { code: \"INTERNAL_ERROR\", message: \"Có lỗi hệ thống\" });\n    } else {\n      response.destroy();\n    }\n  }\n}).listen(3001);\n```\n\n## Phân tích từng bước\n\n1. Status giúp client phân biệt dữ liệu không có và lỗi máy chủ.\n2. Mỗi nhánh phải kết thúc rõ ràng để tránh gửi response lần hai.\n3. Trong ứng dụng thật, thêm log có request ID nhưng không chứa secret.\n\n## Lỗi thường gặp\n\n- Không trả error.stack ra API công khai.\n- Không để promise bị reject mà không có nơi xử lý.\n- Đừng dùng ví dụ health check để kết luận mọi phụ thuộc DB hoặc Redis đều khỏe.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThêm route có lỗi chủ động và xác nhận body không chứa đường dẫn source code hoặc biến môi trường.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Phân biệt lỗi nghiệp vụ với lỗi bất ngờ và tránh để lộ stack trace trong phản hồi HTTP.\n","ordinal":11,"authorOrdinal":1},{"file":"articles/12-python-dataclasses.md","title":"Python: dùng dataclass để mô hình hóa kết quả đọc bài","summary":"Tổ chức dữ liệu bằng dataclass bất biến và xử lý danh sách với hàm thuần dễ kiểm thử.","topicName":"Python","tagNames":["Python","Dataclasses","Iterators","Typing"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Python: dùng dataclass để mô hình hóa kết quả đọc bài\n\nTổ chức dữ liệu bằng dataclass bất biến và xử lý danh sách với hàm thuần dễ kiểm thử.\n\n## Bối cảnh\n\nMột đối tượng dữ liệu rõ ràng giúp tránh nhầm khóa khi truyền dictionary giữa nhiều hàm. Dataclass giảm phần code khởi tạo nhưng vẫn cho phép diễn đạt mô hình.\n\n## Ý tưởng chính\n\nVí dụ dùng frozen=True để ngăn gán lại trường qua thao tác thông thường. Điều đó không biến mọi đối tượng con thành bất biến sâu; vẫn cần chú ý khi trường chứa list hoặc dictionary.\n\n## Ví dụ minh họa\n\n```python\nfrom dataclasses import dataclass\nfrom typing import Iterable\n\n@dataclass(frozen=True)\nclass ArticleSummary:\n    title: str\n    topic: str\n    reading_minutes: int\n\ndef short_articles(items: Iterable[ArticleSummary]) -> list[str]:\n    return [\n        item.title\n        for item in items\n        if 0 < item.reading_minutes <= 5\n    ]\n\narticles = [\n    ArticleSummary(\"Hiểu OOP\", \"Java Core\", 4),\n    ArticleSummary(\"Thiết kế hệ thống\", \"System Design\", 12),\n]\n\nprint(short_articles(articles))\n```\n\n## Phân tích từng bước\n\n1. Type hint diễn đạt ý định nhưng Python không tự cưỡng chế mọi kiểu lúc runtime.\n2. Hàm thuần không sửa dữ liệu đầu vào nên dễ kiểm tra kết quả.\n3. Iterable cho phép nhận nhiều dạng nguồn dữ liệu thay vì chỉ list.\n\n## Lỗi thường gặp\n\n- Không dùng giá trị mặc định mutable dùng chung giữa các instance.\n- Không giả định frozen=True bảo vệ mọi cấu trúc lồng nhau.\n- Kiểm tra miền giá trị như reading_minutes ở ranh giới dữ liệu thật.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nViết test cho danh sách rỗng, thời gian bằng 0, bằng 5 và lớn hơn 5 phút.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Tổ chức dữ liệu bằng dataclass bất biến và xử lý danh sách với hàm thuần dễ kiểm thử.\n","ordinal":12,"authorOrdinal":3},{"file":"articles/13-algorithms-binary-search.md","title":"Thuật toán: tìm kiếm nhị phân và lỗi lệch một vị trí","summary":"Hiểu bất biến khoảng tìm kiếm và các test biên giúp phát hiện lỗi trong binary search.","topicName":"Data Structures & Algorithms","tagNames":["Algorithms","Hash Map","Binary Search","Big O"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# Thuật toán: tìm kiếm nhị phân và lỗi lệch một vị trí\n\nHiểu bất biến khoảng tìm kiếm và các test biên giúp phát hiện lỗi trong binary search.\n\n## Bối cảnh\n\nTìm kiếm nhị phân giảm dần phạm vi cần xét, nhưng chỉ phù hợp khi dữ liệu có thứ tự theo điều kiện đang tìm. Lỗi thường không nằm ở ý tưởng mà ở cách cập nhật hai đầu khoảng.\n\n## Ý tưởng chính\n\nVí dụ dùng khoảng đóng từ left đến right. Sau mỗi lượt, nếu giá trị giữa không phải kết quả thì loại bỏ luôn vị trí đó. Không trộn công thức của khoảng đóng với khoảng nửa mở.\n\n## Ví dụ minh họa\n\n```java\nstatic int binarySearch(int[] values, int target) {\n    int left = 0;\n    int right = values.length - 1;\n\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (values[mid] == target) {\n            return mid;\n        }\n        if (values[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return -1;\n}\n```\n\n## Phân tích từng bước\n\n1. Đầu vào phải được sắp xếp tăng dần.\n2. Mỗi lượt thu hẹp khoảng vì mid đã được kiểm tra.\n3. Độ phức tạp thời gian là O(log n); bộ nhớ phụ của phiên bản lặp là O(1).\n\n## Lỗi thường gặp\n\n- Nếu có phần tử trùng, phiên bản này không bảo đảm trả vị trí xuất hiện đầu tiên.\n- Đặt left = mid có thể làm vòng lặp không tiến triển.\n- Sắp xếp lại dữ liệu cũng có chi phí; không bỏ qua khi tính toàn bộ bài toán.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nTest mảng rỗng, một phần tử, phần tử đầu/cuối, không tìm thấy và nhiều phần tử trùng.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Hiểu bất biến khoảng tìm kiếm và các test biên giúp phát hiện lỗi trong binary search.\n","ordinal":13,"authorOrdinal":3},{"file":"articles/14-rest-api-pagination.md","title":"REST API: phân trang ổn định và filter rõ ràng","summary":"Thiết kế danh sách bài viết với filter tùy chọn, giới hạn kích thước trang và thứ tự nhất quán.","topicName":"REST API Design","tagNames":["REST API","Pagination","Idempotency","HTTP"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# REST API: phân trang ổn định và filter rõ ràng\n\nThiết kế danh sách bài viết với filter tùy chọn, giới hạn kích thước trang và thứ tự nhất quán.\n\n## Bối cảnh\n\nDanh sách là một API dễ viết nhưng dễ gây nhầm khi số lượng dữ liệu tăng. Cần thống nhất page bắt đầu từ đâu, size tối đa và điều kiện lọc được kết hợp như thế nào.\n\n## Ý tưởng chính\n\nVí dụ hợp đồng bên dưới mang tính minh họa, không cam kết tên query parameter của endpoint TechVerse. Trong API thật, đọc DTO filter và Swagger trước khi gửi request.\n\n## Ví dụ minh họa\n\n```http\nGET /articles?page=0&size=20&topicId=TOPIC_UUID&keyword=java\nAccept: application/json\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{\n  \"data\": {\n    \"content\": [\n      { \"id\": \"ARTICLE_UUID\", \"title\": \"Java OOP\" }\n    ],\n    \"page\": 0,\n    \"size\": 20,\n    \"hasNext\": false\n  }\n}\n```\n\n## Phân tích từng bước\n\n1. Cho biết keyword áp dụng vào trường nào và cách xử lý chuỗi rỗng.\n2. Dùng tiêu chí phụ như id khi hai bản ghi có cùng publishedAt.\n3. Giới hạn size ở backend, không tin giới hạn do frontend gửi.\n\n## Lỗi thường gặp\n\n- Offset pagination có thể lặp hoặc bỏ sót khi dữ liệu thay đổi giữa các lần đọc.\n- Không truyền trực tiếp tên cột từ query string vào SQL.\n- Filter của admin và người đọc có thể giống hình thức nhưng khác phạm vi dữ liệu được phép xem.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nTạo ba bài cùng topic, lọc theo tag rồi đổi page; kiểm tra chỉ bài đã publish được trả cho người đọc.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Thiết kế danh sách bài viết với filter tùy chọn, giới hạn kích thước trang và thứ tự nhất quán.\n","ordinal":14,"authorOrdinal":1},{"file":"articles/15-docker-compose-local.md","title":"Docker Compose: tổ chức PostgreSQL và Redis cho môi trường local","summary":"Đọc cấu hình dịch vụ, volume và health check mà không nhầm địa chỉ giữa container và máy host.","topicName":"Docker & Containers","tagNames":["Docker","Docker Compose","Containers","Health Checks"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Docker Compose: tổ chức PostgreSQL và Redis cho môi trường local\n\nĐọc cấu hình dịch vụ, volume và health check mà không nhầm địa chỉ giữa container và máy host.\n\n## Bối cảnh\n\nKhi backend chạy trên máy còn PostgreSQL nằm trong container, host kết nối khác với trường hợp backend cũng nằm trong Compose. Hiểu ranh giới mạng giúp tránh nhiều lỗi connection refused.\n\n## Ý tưởng chính\n\nĐoạn cấu hình này dành cho học tập trong một thư mục demo riêng. Không ghi đè compose.yaml hiện có của TechVerse. Dùng giá trị môi trường riêng và không commit mật khẩu thực.\n\n## Ví dụ minh họa\n\n```yaml\nservices:\n  database:\n    image: postgres:16-alpine\n    environment:\n      POSTGRES_DB: demo\n      POSTGRES_USER: demo\n      POSTGRES_PASSWORD: ${DEMO_DB_PASSWORD:?Set DEMO_DB_PASSWORD}\n    volumes:\n      - demo_pg_data:/var/lib/postgresql/data\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U demo -d demo\"]\n      interval: 5s\n      timeout: 3s\n      retries: 10\n\n  cache:\n    image: redis:7-alpine\n    healthcheck:\n      test: [\"CMD\", \"redis-cli\", \"ping\"]\n      interval: 5s\n      timeout: 3s\n      retries: 10\n\nvolumes:\n  demo_pg_data:\n```\n\n## Phân tích từng bước\n\n1. Hai service cùng mạng Compose có thể gọi tên database và cache.\n2. Không khai báo ports thì ví dụ không mở cổng cho máy host truy cập.\n3. Volume giữ dữ liệu qua việc tạo lại container, nhưng không thay thế backup.\n\n## Lỗi thường gặp\n\n- localhost bên trong container là chính container đó.\n- depends_on thông thường không đồng nghĩa database đã sẵn sàng nhận truy vấn.\n- Không chạy down -v trên dự án thật nếu chưa hiểu dữ liệu nào sẽ bị xóa.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nGiải thích địa chỉ kết nối khi backend chạy trong Compose và khi backend chạy từ IntelliJ trên host.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Đọc cấu hình dịch vụ, volume và health check mà không nhầm địa chỉ giữa container và máy host.\n","ordinal":15,"authorOrdinal":4},{"file":"articles/16-ci-workflow-quality-gate.md","title":"CI/CD: xây dựng quality gate trước khi merge","summary":"Sắp xếp kiểm tra dependency, test và build để phát hiện lỗi sớm trước khi đưa code vào nhánh chính.","topicName":"CI/CD & DevOps","tagNames":["CI/CD","GitHub Actions","Build Automation","Environment Variables"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# CI/CD: xây dựng quality gate trước khi merge\n\nSắp xếp kiểm tra dependency, test và build để phát hiện lỗi sớm trước khi đưa code vào nhánh chính.\n\n## Bối cảnh\n\nCI không chỉ là một huy hiệu xanh. Nó là cách chạy cùng một bộ kiểm tra cho mọi thành viên, tránh việc code chỉ hoạt động trên một máy.\n\n## Ý tưởng chính\n\nĐoạn lệnh thể hiện các bước cốt lõi có thể đưa vào workflow. Cần dùng đúng đường dẫn và hệ điều hành của runner. Không cần thêm bước deploy khi mục tiêu hiện tại chỉ là bảo đảm thay đổi có thể test và build.\n\n## Ví dụ minh họa\n\n```bash\n# Ví dụ trên Linux runner, tại repository root.\n# Dùng lockfile đã commit để cài dependency nhất quán.\n(cd app && npm ci && npm test && npm run build)\n\n# Gradle Wrapper dùng phiên bản Gradle của dự án.\n(cd server && ./gradlew test bootJar)\n```\n\n## Phân tích từng bước\n\n1. Dùng npm ci trong CI thay vì tự thay lockfile trong lúc build.\n2. Kiểm thử backend cần cấu hình test riêng, không dùng database production.\n3. Job phải thất bại khi lệnh kiểm tra thất bại; không thêm bỏ qua lỗi chỉ để workflow xanh.\n\n## Lỗi thường gặp\n\n- Không đưa .env thật vào artifact hoặc log CI.\n- Không cấp quyền ghi hoặc secret cho job không cần đến chúng.\n- Cache dependency không phải bằng chứng rằng source hiện tại đã build thành công.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThiết kế hai job độc lập cho app và server; liệt kê secret nào thật sự cần và secret nào không được cấp.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Sắp xếp kiểm tra dependency, test và build để phát hiện lỗi sớm trước khi đưa code vào nhánh chính.\n","ordinal":16,"authorOrdinal":4},{"file":"articles/17-testing-validation-boundaries.md","title":"Testing: kiểm thử biên thay vì chỉ kiểm tra happy path","summary":"Từ một hàm kiểm tra độ dài tên, xây dựng các ca rỗng, sát giới hạn và vượt giới hạn.","topicName":"Software Testing","tagNames":["Unit Testing","Integration Testing","JUnit","Mockito"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# Testing: kiểm thử biên thay vì chỉ kiểm tra happy path\n\nTừ một hàm kiểm tra độ dài tên, xây dựng các ca rỗng, sát giới hạn và vượt giới hạn.\n\n## Bối cảnh\n\nMột test thành công chỉ chứng minh đúng tình huống mà nó đã chạy. Với dữ liệu nhập, các giá trị sát biên thường tìm ra lỗi tốt hơn những dữ liệu ngẫu nhiên luôn hợp lệ.\n\n## Ý tưởng chính\n\nVí dụ JUnit kiểm tra một hàm nhỏ để thấy rõ quan hệ giữa yêu cầu và test. Đây là quy ước độ dài tính theo String.length, không phải bộ đếm ký tự hiển thị Unicode.\n\n## Ví dụ minh họa\n\n```java\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\n\nclass NamePolicyTest {\n    private boolean valid(String name) {\n        return name != null\n            && !name.isBlank()\n            && name.strip().length() <= 100;\n    }\n\n    @Test\n    void rejectsMissingOrBlankName() {\n        assertFalse(valid(null));\n        assertFalse(valid(\"   \"));\n    }\n\n    @Test\n    void checksTheLengthBoundary() {\n        assertTrue(valid(\"a\".repeat(100)));\n        assertFalse(valid(\"a\".repeat(101)));\n    }\n}\n```\n\n## Phân tích từng bước\n\n1. Tên test nên thể hiện quy tắc cần bảo vệ.\n2. Test API còn cần kiểm tra status, body và dữ liệu thực sự đã được thay đổi hay chưa.\n3. Với thao tác dùng một lần, bổ sung test đồng thời thay vì chỉ gọi tuần tự.\n\n## Lỗi thường gặp\n\n- Không chỉ assert rằng mock đã được gọi rồi kết luận nghiệp vụ đúng.\n- Không dùng sleep cố định dài để tạo race condition nếu có thể dùng barrier hoặc latch.\n- Không bỏ qua test fail vì cho rằng nó không liên quan mà chưa điều tra.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nTạo ma trận test cho OTP: đúng, sai, hết hạn, đã dùng và hai request cùng dùng một mã.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Từ một hàm kiểm tra độ dài tên, xây dựng các ca rỗng, sát giới hạn và vượt giới hạn.\n","ordinal":17,"authorOrdinal":4},{"file":"articles/18-git-feature-branch.md","title":"Git teamwork: tạo feature branch và đồng bộ main an toàn","summary":"Thực hành tên branch, commit message và merge mà không dùng force push để giải quyết nhầm xung đột.","topicName":"Git & Teamwork","tagNames":["Git","Branching","Commit Convention","Merge"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Git teamwork: tạo feature branch và đồng bộ main an toàn\n\nThực hành tên branch, commit message và merge mà không dùng force push để giải quyết nhầm xung đột.\n\n## Bối cảnh\n\nNhóm nhỏ vẫn cần quy ước rõ. Một nhánh nên có mục tiêu dễ hiểu, commit mô tả thay đổi cụ thể và quá trình merge giữ lại được lịch sử làm việc.\n\n## Ý tưởng chính\n\nVí dụ theo tên feature mang tính nghiệp vụ, dùng được cho cả frontend và backend. Trước khi đổi nhánh cần kiểm tra thay đổi chưa commit để không mang nhầm code sang nhiệm vụ khác.\n\n## Ví dụ minh họa\n\n```bash\ngit status\ngit switch main\ngit pull --ff-only origin main\ngit switch -c feature/article-bookmarks\n\n# Sau khi hoàn thành phần thay đổi và tự kiểm tra:\ngit add app/src server/src\ngit commit -m \"feat(bookmarks): add save and unsave article\"\ngit push -u origin feature/article-bookmarks\n\n# Tích hợp khi nhóm đã thống nhất và working tree sạch:\ngit switch main\ngit pull --ff-only origin main\ngit merge feature/article-bookmarks\ngit push origin main\n```\n\n## Phân tích từng bước\n\n1. feat, fix, refactor và test giúp nhận diện mục đích của commit.\n2. git add trong ví dụ cần được điều chỉnh theo file thực sự thuộc nhiệm vụ.\n3. Khi --ff-only báo lệch lịch sử, dừng để xem graph trước khi chọn cách tích hợp.\n\n## Lỗi thường gặp\n\n- Không dùng push --force lên main để xử lý non-fast-forward.\n- Không commit .env, key dịch vụ hoặc token đăng nhập.\n- Không xóa thay đổi của người khác để làm working tree sạch.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nViết ba commit message cho tạo bài viết, sửa upload ảnh bìa và thêm test refresh đồng thời.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Thực hành tên branch, commit message và merge mà không dùng force push để giải quyết nhầm xung đột.\n","ordinal":18,"authorOrdinal":4},{"file":"articles/19-system-design-atomic-redis.md","title":"System design: thao tác Redis nguyên tử để dùng token một lần","summary":"Phân tích khoảng hở giữa kiểm tra và xóa, cùng ví dụ Lua tối giản cho một khóa token đã băm.","topicName":"System Design","tagNames":["System Design","Concurrency","Rate Limiting","Scalability"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# System design: thao tác Redis nguyên tử để dùng token một lần\n\nPhân tích khoảng hở giữa kiểm tra và xóa, cùng ví dụ Lua tối giản cho một khóa token đã băm.\n\n## Bối cảnh\n\nNếu hai request cùng đọc một token còn hiệu lực trước khi bất kỳ request nào xóa nó, cả hai có thể được chấp nhận. Đây là lỗi kiểm tra rồi hành động ở hai bước riêng.\n\n## Ý tưởng chính\n\nLua trong Redis cho phép gộp kiểm tra và xóa thành một thao tác nguyên tử. Ví dụ giả định khóa chứa hash token và bên gọi đã băm token nhận được. Đây không phải cơ chế OTP sáu số đầy đủ: OTP cần thêm giới hạn thử, rate limit và cách bảo vệ hash phù hợp.\n\n## Ví dụ minh họa\n\n```lua\n-- KEYS[1]: key of a short-lived token record\n-- ARGV[1]: expected hash computed by the server\nlocal stored = redis.call(\"GET\", KEYS[1])\n\nif not stored then\n    return 0\nend\n\nif stored ~= ARGV[1] then\n    return 0\nend\n\nredis.call(\"DEL\", KEYS[1])\nreturn 1\n```\n\n## Phân tích từng bước\n\n1. Chỉ một lần gọi có thể thấy giá trị đúng và xóa khóa thành công.\n2. TTL vẫn phải được đặt ở lúc tạo khóa.\n3. Atomicity của Redis không tạo ra transaction chung với PostgreSQL; luồng đổi mật khẩu phải xử lý ranh giới này riêng.\n\n## Lỗi thường gặp\n\n- Không dùng hash SHA-256 đơn thuần cho OTP ít khả năng nếu cần chống dò offline; cân nhắc HMAC với secret server.\n- Không trả token reset vào log.\n- Không coi Lua là giải pháp thay thế rate limit cho endpoint công khai.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nDùng hai client đồng thời gọi script với cùng token rồi kiểm tra chỉ một kết quả bằng 1.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Phân tích khoảng hở giữa kiểm tra và xóa, cùng ví dụ Lua tối giản cho một khóa token đã băm.\n","ordinal":19,"authorOrdinal":3},{"file":"articles/20-network-debugging.md","title":"Linux và networking: chẩn đoán kết nối theo từng lớp","summary":"Tách vấn đề DNS, TCP, TLS và HTTP để tìm đúng nguyên nhân khi frontend không gọi được backend.","topicName":"Linux & Networking","tagNames":["Linux","TCP/IP","DNS","Reverse Proxy"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# Linux và networking: chẩn đoán kết nối theo từng lớp\n\nTách vấn đề DNS, TCP, TLS và HTTP để tìm đúng nguyên nhân khi frontend không gọi được backend.\n\n## Bối cảnh\n\nMột lỗi Request failed có thể đến từ sai hostname, cổng chưa mở, chứng chỉ TLS hoặc backend trả 403. Kiểm tra theo từng lớp giúp tránh sửa ngẫu nhiên cấu hình ứng dụng.\n\n## Ý tưởng chính\n\nCác lệnh dưới là ví dụ đọc thông tin trong môi trường local hoặc Linux có công cụ tương ứng. Không quét hay kiểm tra hệ thống ngoài phạm vi mình quản lý.\n\n## Ví dụ minh họa\n\n```bash\n# 1. Kiểm tra phân giải tên; có thể cần cài công cụ DNS.\nnslookup localhost\n\n# 2. Liệt kê socket đang lắng nghe trên Linux.\nss -ltn\n\n# 3. Quan sát status và header từ dịch vụ local.\ncurl -i --max-time 5 http://localhost:8080/\n\n# 4. Chỉ kiểm tra đường mạng đến endpoint được phép.\n# 404 hoặc 401 vẫn cho thấy đã có phản hồi HTTP từ server.\n```\n\n## Phân tích từng bước\n\n1. Connection refused khác với phản hồi HTTP 401 hoặc 403.\n2. CORS là quy tắc áp dụng bởi trình duyệt; curl thành công không chứng minh cấu hình CORS đã đúng.\n3. Reverse proxy có thể đổi đường dẫn hoặc header trước khi request đến backend.\n\n## Lỗi thường gặp\n\n- Không chia sẻ file HAR khi chưa loại bỏ cookie và Authorization.\n- Không tắt TLS verification làm cách sửa lâu dài.\n- Không công khai cổng database chỉ để giải quyết sai cấu hình mạng nội bộ.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nMô tả lần lượt việc kiểm tra khi Swagger truy cập được nhưng trang React báo lỗi gọi API.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Tách vấn đề DNS, TCP, TLS và HTTP để tìm đúng nguyên nhân khi frontend không gọi được backend.\n","ordinal":20,"authorOrdinal":4},{"file":"articles/21-clean-code-strategy.md","title":"Clean Code: Strategy Pattern cho nhiều cách định dạng nội dung","summary":"Tách thuật toán biến đổi nội dung khỏi bộ điều phối, tránh một hàm lớn chứa nhiều điều kiện khó thay đổi.","topicName":"Clean Code & Design Patterns","tagNames":["Clean Code","SOLID","Strategy Pattern","Refactoring"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Clean Code: Strategy Pattern cho nhiều cách định dạng nội dung\n\nTách thuật toán biến đổi nội dung khỏi bộ điều phối, tránh một hàm lớn chứa nhiều điều kiện khó thay đổi.\n\n## Bối cảnh\n\nKhi hỗ trợ cả Markdown và văn bản thuần, hai loại dữ liệu có cách xử lý khác nhau. Một bộ điều phối nhỏ có thể chọn chiến lược phù hợp mà không gộp tất cả vào một hàm dài.\n\n## Ý tưởng chính\n\nStrategy Pattern đóng gói các cách thực hiện có thể thay thế. Mẫu này hữu ích khi các thuật toán thật sự có vòng đời riêng; với hai nhánh ngắn ổn định, if/else có thể đơn giản hơn.\n\n## Ví dụ minh họa\n\n```java\ninterface ContentFormatter {\n    String format(String input);\n}\n\nfinal class MarkdownFormatter implements ContentFormatter {\n    @Override\n    public String format(String input) {\n        return input.strip();\n    }\n}\n\nfinal class ImportPreview {\n    private final ContentFormatter formatter;\n\n    ImportPreview(ContentFormatter formatter) {\n        this.formatter = formatter;\n    }\n\n    String preview(String text) {\n        if (text == null || text.isBlank()) {\n            throw new IllegalArgumentException(\"Empty content\");\n        }\n        return formatter.format(text);\n    }\n}\n```\n\n## Phân tích từng bước\n\n1. Interface thể hiện điểm thay đổi là cách format, không phải toàn bộ nghiệp vụ import.\n2. Kiểm tra định dạng file và kích thước vẫn cần ở ranh giới upload.\n3. Ví dụ không sanitize HTML; validate nội dung là trách nhiệm bổ sung.\n\n## Lỗi thường gặp\n\n- Không biến một đoạn strip thành hàng loạt abstraction trong sản phẩm nhỏ nếu chưa có nhu cầu.\n- Không nhầm định dạng Markdown với việc thực thi code.\n- Không bỏ cơ chế an toàn của renderer vì đã dùng một formatter.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nThêm PlainTextFormatter có quy tắc escape rõ ràng và viết test với dấu sao, backtick và thẻ HTML.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Tách thuật toán biến đổi nội dung khỏi bộ điều phối, tránh một hàm lớn chứa nhiều điều kiện khó thay đổi.\n","ordinal":21,"authorOrdinal":1},{"file":"articles/22-observability-request-id.md","title":"Observability: dùng request ID để nối các bước xử lý","summary":"Theo dõi một request qua controller, service và lời gọi dịch vụ ngoài mà không log dữ liệu nhạy cảm.","topicName":"Observability","tagNames":["Logging","Metrics","Tracing","Correlation ID"],"coverImageUrl":"https://images.unsplash.com/photo-1487058792275-0ad4aaf24ca7?auto=format&fit=crop&w=1200&q=80","content":"# Observability: dùng request ID để nối các bước xử lý\n\nTheo dõi một request qua controller, service và lời gọi dịch vụ ngoài mà không log dữ liệu nhạy cảm.\n\n## Bối cảnh\n\nKhi nhiều người đăng ký cùng lúc, chỉ tìm theo thời gian trong log rất dễ nhầm. Request ID giúp liên kết những dòng log thuộc cùng một lần xử lý.\n\n## Ý tưởng chính\n\nMột request ID được tạo hoặc kiểm tra tại điểm vào rồi truyền theo ngữ cảnh. Nếu nhận từ client, phải giới hạn chiều dài và ký tự. Với tác vụ Async, việc truyền ngữ cảnh cần được cấu hình riêng.\n\n## Ví dụ minh họa\n\n```text\nrequestId=demo-req-001 event=article_submit_started articleId=demo-article\nrequestId=demo-req-001 event=article_validation_passed\nrequestId=demo-req-001 event=article_submit_completed status=PENDING durationMs=42\n\nrequestId=demo-req-002 event=email_send_started template=register-success\nrequestId=demo-req-002 event=email_provider_rejected status=401\n```\n\n## Phân tích từng bước\n\n1. Event name ổn định giúp tìm kiếm và tổng hợp log.\n2. Duration hỗ trợ nhận diện phần xử lý chậm, không thay thế metric phân phối độ trễ.\n3. Lỗi nhà cung cấp email nên được phân biệt với lỗi đăng ký tài khoản.\n\n## Lỗi thường gặp\n\n- Không ghi API key, refresh cookie, mật khẩu hoặc OTP vào log.\n- Không đưa userId hoặc requestId vào metric label có số giá trị không giới hạn.\n- Không giả định ThreadLocal tự theo sang thread của @Async.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nĐịnh nghĩa năm event cho luồng gửi OTP, xác minh OTP và đổi mật khẩu; chỉ ra dữ liệu nào bị cấm log.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Theo dõi một request qua controller, service và lời gọi dịch vụ ngoài mà không log dữ liệu nhạy cảm.\n","ordinal":22,"authorOrdinal":4},{"file":"articles/23-web-performance-debounce.md","title":"Web performance: debounce tìm kiếm mà không hiển thị kết quả cũ","summary":"Kết hợp khoảng chờ gõ với hủy request trước đó để giảm tải và tránh kết quả về sai thứ tự.","topicName":"Web Performance","tagNames":["Performance","Lazy Loading","Debouncing","Web Vitals"],"coverImageUrl":"https://images.unsplash.com/photo-1760670399462-f5e479452c27?auto=format&fit=crop&w=1200&q=80","content":"# Web performance: debounce tìm kiếm mà không hiển thị kết quả cũ\n\nKết hợp khoảng chờ gõ với hủy request trước đó để giảm tải và tránh kết quả về sai thứ tự.\n\n## Bối cảnh\n\nNgười dùng gõ một từ có thể tạo ra nhiều lần thay đổi input. Gửi request ở mỗi ký tự vừa tốn tài nguyên vừa dễ gặp tình huống request cũ trả về sau request mới.\n\n## Ý tưởng chính\n\nDebounce gom các thay đổi gần nhau; AbortController giúp hủy request không còn cần thiết. Đoạn hook dưới tập trung vào cleanup, chưa triển khai phân trang hoặc luồng Bearer token của dự án.\n\n## Ví dụ minh họa\n\n```jsx\nimport { useEffect, useState } from \"react\";\n\nexport function useSearch(keyword) {\n  const [items, setItems] = useState([]);\n\n  useEffect(() => {\n    const controller = new AbortController();\n    let active = true;\n\n    const timer = setTimeout(async () => {\n      try {\n        const response = await fetch(\n          \"/api/demo/search?q=\" + encodeURIComponent(keyword),\n          { signal: controller.signal }\n        );\n        if (!response.ok) throw new Error(\"Search failed\");\n        const data = await response.json();\n        if (active) setItems(data.items ?? []);\n      } catch (error) {\n        if (active) {\n          // App thật cần hiển thị trạng thái lỗi phù hợp.\n          setItems([]);\n        }\n      }\n    }, 300);\n\n    return () => {\n      active = false;\n      clearTimeout(timer);\n      controller.abort();\n    };\n  }, [keyword]);\n\n  return items;\n}\n```\n\n## Phân tích từng bước\n\n1. Cleanup hủy cả timer chưa chạy và request đang xử lý.\n2. encodeURIComponent ngăn từ khóa làm sai cấu trúc query string.\n3. Trong dự án dùng request helper chung thì bổ sung signal qua helper để giữ cơ chế xác thực.\n\n## Lỗi thường gặp\n\n- Debounce không thay thế rate limit phía server.\n- Không giữ dữ liệu của người dùng trước khi đổi tài khoản.\n- Không giả định response luôn có trường items như ví dụ minh họa.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nLàm request cho từ khóa cũ chậm hơn từ khóa mới, sau đó xác nhận danh sách không bị ghi đè bởi kết quả cũ.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Kết hợp khoảng chờ gõ với hủy request trước đó để giảm tải và tránh kết quả về sai thứ tự.\n","ordinal":23,"authorOrdinal":2},{"file":"articles/24-ai-safe-integration.md","title":"Tích hợp AI: coi đầu ra mô hình là dữ liệu chưa được tin cậy","summary":"Thiết kế ranh giới dữ liệu, kiểm tra đầu ra và kiểm soát chi phí khi thêm AI vào ứng dụng học tập.","topicName":"AI Integration","tagNames":["AI","LLM","Prompting","Data Privacy"],"coverImageUrl":"https://images.unsplash.com/photo-1638602612226-55fd638475c9?auto=format&fit=crop&w=1200&q=80","content":"# Tích hợp AI: coi đầu ra mô hình là dữ liệu chưa được tin cậy\n\nThiết kế ranh giới dữ liệu, kiểm tra đầu ra và kiểm soát chi phí khi thêm AI vào ứng dụng học tập.\n\n## Bối cảnh\n\nMột tính năng tóm tắt bài viết có thể hữu ích, nhưng đầu vào bài viết và đầu ra mô hình không nên được trao quyền trực tiếp lên hệ thống. Nội dung văn bản có thể chứa chỉ dẫn không đáng tin.\n\n## Ý tưởng chính\n\nBackend cần tự quyết định dữ liệu nào được phép gửi cho nhà cung cấp. Model không quyết định quyền đọc bài, quyền cập nhật database hoặc quyền gọi công cụ. Schema đầu ra và các giới hạn là lớp bảo vệ, không phải lời bảo đảm tuyệt đối về tính đúng.\n\n## Ví dụ minh họa\n\n```text\nsummarizeArticle(actor, articleId):\n    require actor can read articleId\n    load the allowed article content\n    remove secrets and unnecessary personal data\n    enforce request size, quota and timeout\n\n    call provider using server-side credentials\n    treat article content as untrusted reference material\n    require a structured summary response\n\n    validate returned fields and maximum lengths\n    render as escaped text\n    return summary without granting any new permissions\n```\n\n## Phân tích từng bước\n\n1. Secret của nhà cung cấp chỉ nằm ở backend, không nằm trong biến frontend public.\n2. Đặt timeout và giới hạn đầu vào, đầu ra để quản lý chi phí.\n3. Nếu lưu kết quả cache, gắn với phiên bản hoặc dấu vân tay nội dung bài viết.\n\n## Lỗi thường gặp\n\n- Prompt injection không được giải quyết chỉ bằng câu 'hãy bỏ qua chỉ dẫn xấu'.\n- Không gửi mật khẩu, JWT, cookie hoặc dữ liệu riêng tư không cần thiết.\n- Không render HTML đầu ra của model một cách không kiểm soát.\n\n> Code trong bài phục vụ học tập. Hãy điều chỉnh theo kiến trúc, phiên bản thư viện và quy tắc bảo mật của dự án trước khi sử dụng.\n\n## Bài tập thực hành\n\nTạo một bài viết chứa câu yêu cầu tiết lộ secret và chứng minh hệ thống không có đường cấp secret cho model.\n\n## Checklist tự kiểm tra\n\n- Đã giải thích được đầu vào, đầu ra và giới hạn của ví dụ.\n- Đã nghĩ tới dữ liệu rỗng, dữ liệu không hợp lệ và tình huống thất bại.\n- Đã tách phần minh họa khỏi cấu hình và bí mật của môi trường thật.\n\n---\n\n**Kết luận:** Thiết kế ranh giới dữ liệu, kiểm tra đầu ra và kiểm soát chi phí khi thêm AI vào ứng dụng học tập.\n","ordinal":24,"authorOrdinal":3}]}$demo_data$::jsonb);

CREATE TEMP TABLE demo_admin ON COMMIT DROP AS
SELECT u.id FROM users u JOIN user_roles ur ON ur.user_id = u.id
JOIN roles r ON r.id = ur.role_id
WHERE u.is_active AND r.name = 'ADMIN' ORDER BY u.created_at, u.id LIMIT 1;

CREATE TEMP TABLE demo_authors ON COMMIT DROP AS
SELECT md5('techverse.demo.author.' || (a->>'ordinal'))::uuid AS id,
       (a->>'ordinal')::int AS ordinal, a->>'name' AS full_name,
       a->>'email' AS email, a->>'expertise' AS expertise, a->>'bio' AS bio
FROM demo_payload, jsonb_array_elements(data->'authors') a;

CREATE TEMP TABLE demo_articles ON COMMIT DROP AS
SELECT md5('techverse.demo.article.' || (a->>'file'))::uuid AS id,
       (a->>'ordinal')::int AS ordinal,
       md5('techverse.demo.author.' || (a->>'authorOrdinal'))::uuid AS author_id,
       a->>'title' AS title, a->>'summary' AS summary, a->>'content' AS content,
       a->>'topicName' AS topic_name, a->'tagNames' AS tag_names,
       a->>'coverImageUrl' AS cover_image_url
FROM demo_payload, jsonb_array_elements(data->'articles') a;

-- Fail instead of taking over unrelated accounts or silently omitting taxonomy.
DO $guard$
BEGIN
    IF EXISTS (
        SELECT 1 FROM demo_authors d JOIN users u ON u.id = d.id OR u.email = d.email::citext
        WHERE u.id <> d.id OR u.email <> d.email::citext
    ) THEN
        RAISE EXCEPTION 'Demo account identity collision; no data has been changed';
    END IF;
    IF EXISTS (
        SELECT 1 FROM demo_articles d JOIN articles a ON a.id = d.id
        WHERE a.author_id <> d.author_id OR a.title <> d.title
    ) THEN
        RAISE EXCEPTION 'Demo article identity collision';
    END IF;
    IF EXISTS (
        SELECT 1 FROM demo_articles d LEFT JOIN topics t ON t.name = d.topic_name::citext
        WHERE t.id IS NULL OR NOT t.is_active
    ) OR EXISTS (
        SELECT 1 FROM demo_articles d CROSS JOIN LATERAL jsonb_array_elements_text(d.tag_names) n(name)
        LEFT JOIN tags t ON t.name = n.name::citext WHERE t.id IS NULL OR NOT t.is_active
    ) THEN
        RAISE EXCEPTION 'Required topic/tag missing or inactive; check topics-tags.sql first';
    END IF;
END
$guard$;

INSERT INTO users (id, full_name, email, password, date_of_birth, is_active, created_by, updated_by)
SELECT d.id, d.full_name, d.email, '{bcrypt}' || crypt('TechVerseDemo@2026', gen_salt('bf', 10)),
       DATE '1995-01-01' + d.ordinal, true, a.id, a.id
FROM demo_authors d CROSS JOIN demo_admin a
ON CONFLICT (id) DO NOTHING;

-- LEARNER is also granted explicitly so this remains safe if bootstrap triggers change.
INSERT INTO user_roles (user_id, role_id, created_by, updated_by)
SELECT d.id, r.id, a.id, a.id FROM demo_authors d CROSS JOIN roles r CROSS JOIN demo_admin a
WHERE r.name IN ('LEARNER', 'AUTHOR')
ON CONFLICT (user_id, role_id) DO NOTHING;

INSERT INTO author_profiles (id, user_id, bio, expertise, status, review_note,
    reviewed_by, reviewed_at, created_by, updated_by)
SELECT md5('techverse.demo.profile.' || d.ordinal)::uuid, d.id, d.bio, d.expertise,
       'APPROVED', 'Hồ sơ mẫu chỉ dùng cho development.', a.id, now(), d.id, a.id
FROM demo_authors d CROSS JOIN demo_admin a
ON CONFLICT (user_id) DO NOTHING;

INSERT INTO articles (id, author_id, topic_id, title, summary, content, cover_image_url,
    status, moderation_note, reviewed_by, reviewed_at, published_at,
    created_at, created_by, updated_at, updated_by)
SELECT d.id, d.author_id, t.id, d.title, d.summary, d.content, d.cover_image_url,
       'PUBLISHED', 'Bài viết demo từ bộ Markdown fixture.', a.id,
       now() - (24 - d.ordinal) * interval '1 day',
       now() - (24 - d.ordinal) * interval '1 day',
       now() - (24 - d.ordinal) * interval '1 day' - interval '2 hours',
       d.author_id, now() - (24 - d.ordinal) * interval '1 day', a.id
FROM demo_articles d JOIN topics t ON t.name = d.topic_name::citext CROSS JOIN demo_admin a
ON CONFLICT (id) DO NOTHING;

INSERT INTO article_tags (article_id, tag_id, created_at, created_by, updated_at, updated_by)
SELECT d.id, t.id, ar.created_at, d.author_id, ar.updated_at, d.author_id
FROM demo_articles d JOIN articles ar ON ar.id = d.id
CROSS JOIN LATERAL jsonb_array_elements_text(d.tag_names) n(name)
JOIN tags t ON t.name = n.name::citext
ON CONFLICT (article_id, tag_id) DO NOTHING;

-- Verify the complete fixture before committing.
DO $verify$
BEGIN
    IF (SELECT count(*) FROM users u JOIN demo_authors d ON d.id = u.id
        JOIN author_profiles p ON p.user_id = u.id
        WHERE u.is_active AND p.status = 'APPROVED') <> 4
       OR (SELECT count(*) FROM articles a JOIN demo_articles d ON d.id = a.id
           WHERE a.status = 'PUBLISHED' AND length(a.content) > 100
             AND a.cover_image_url IS NOT NULL AND a.published_at IS NOT NULL) <> 24
       OR (SELECT count(*) FROM article_tags at JOIN demo_articles d ON d.id = at.article_id) <> 96
    THEN
        RAISE EXCEPTION 'Demo fixture validation failed; transaction rolled back';
    END IF;
END
$verify$;
SELECT 'demo_authors' AS fixture, count(*) FROM users u JOIN demo_authors d ON u.id = d.id
UNION ALL SELECT 'demo_published_articles', count(*) FROM articles a JOIN demo_articles d ON a.id = d.id
UNION ALL SELECT 'demo_article_tags', count(*) FROM article_tags at JOIN demo_articles d ON at.article_id = d.id;
COMMIT;

